import {legacyTag,legacyMechanic,legacyName} from './legacy.mjs';
const legacyFeature=legacyMechanic('astrology');
import {speciesReferences} from './species-mechanics.mjs';
import {sourceLabel} from './sources.mjs';
import {chartState,starSign,starEffect,chartXP,chartTalentChoices} from './astrology.mjs';
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function speciesRulePanel(R,s){const text=R.species[s.species].mechanics?.gmApproval;return (text?`<div class="notice"><p>${esc(text)}</p></div>`:'')+speciesReferences(R,s).map(x=>`<div class="notice"><p>${esc(x.text)} <span class="source">${esc(sourceLabel(R,x))}</span></p></div>`).join('');}
export function nameStylePanel(R,s,{select}){if(!R.background[s.species].imperialNames)return '';return `<div class="field"><label for="ogre-name-style">Naming tradition</label>${select('id="ogre-name-style" data-bind="nameStyle"',[['imperial','Imperial names · core p. 27'],['traditional','Traditional Ogre names · Archives II pp. 22–23']],s.nameStyle||'imperial')}</div>`;}
export function nameElementPanel(R,s,{select,button}){
 const tables=s.nameStyle==='traditional'?R.background[s.species].nameElements:null;if(!tables)return '';
 return `<p class="small muted">Combine a root and ending into one given name. Your title/clan name is separate. Archives II pp. 22–23.</p><div class="cols">${tables.map((table,i)=>`<div class="field"><label for="name-element-${i}">${i?'Name ending':'Name root'}</label>${select(`id="name-element-${i}" data-bind="nameElement" data-key="${i}"`,table.rows.map(row=>[String(row.min),row.result]),String(s.nameElements?.[i]||''),true)}</div>`).join('')}</div>${button('traditional-name','Roll traditional given name · 2 × d100')}`;
}
export function astrologyPanel(R,s,{select,button,options}){
 if(!R.astrology?.length)return '';
 const chart=chartState(s),sign=starSign(R,s),effect=starEffect(R,s),talents=chartTalentChoices(R,s,options);
 const choices=R.astrology.map(x=>[x.id,x.name]);
 return `<section class="section-gap"><h2>Star sign ${legacyTag(R,legacyFeature)} <span class="source">Archives II p. 39</span></h2><label class="check-row"><input type="checkbox" data-bind="chartEnabled" ${chart.enabled?'checked':''}>Use the optional star-sign creation rules</label>${!chart.enabled?'':`<p class="small muted">Apply this after generating Characteristics. Keep your initial d100 result for +25 XP, or choose another sign with no reward. Ascendant and mansion signs are background only.</p><div class="actions">${button('star-roll',chart.rolledSign?'Initial roll recorded':'Roll star sign · d100',chart.rolledSign?'disabled':'','primary')}</div>${chart.rolledSign?`<div class="field"><label for="star-sign">Your star sign</label>${select('id="star-sign" data-bind="starSign"',choices,chart.sign)}</div>`:''}${sign?`<div class="notice"><strong>${esc(sign.name)}</strong> ${legacyTag(R,sign)}<p>${Object.entries(effect.adjustments||{}).map(([key,value])=>`${key} ${value>=0?'+':''}${value}`).join(' · ')||'No Characteristic change for this result.'}${effect.talent?` · Talent: ${esc(effect.talent)}`:''}</p><p class="small">${chartXP(R,s)?'+25 creation XP · initial sign retained':'No bonus XP · sign changed'} · These adjustments are not Advances.</p>${sign.witchling?`<p class="small">Detailed p. 39 table: 1–3 Sixth Sense, no penalty; 4–6 Second Sight, S −3; 7–9 Petty Magic, S −3; 10 Witch!, S −5. This resolves p. 47’s general −3 penalty as agreed.</p>${chart.witchling?`<strong>Witchling d10: ${chart.witchling}</strong>`:button('witchling-roll','Roll Witchling effect · d10')}`:''}</div>${talents.length?`<div class="field"><label for="star-talent">Craftsman specialisation</label>${select('id="star-talent" data-bind="starTalent"',talents,chart.talent,true)}</div>`:''}<details><summary>Your sign’s description · Archives II p. ${sign.profilePage}</summary><p>${esc(sign.text)}</p><p class="small">Classical name: ${esc(sign.classical)} · Ascendant: ${esc(sign.ascendant)} · Dates: ${esc(sign.calendar)} · Associated god: ${esc(sign.god)} · Appearance: ${esc(sign.appearance)}</p></details><details class="section-gap"><summary>More about your chart · optional background</summary><p class="small muted">Archives II p. 50. These signs describe first impressions and areas of your life; they add no Characteristic, Talent or XP bonuses.</p><p>Ascendant: <strong>${esc(R.astrology.find(x=>x.id===chart.ascendant)?.name||'Not rolled')}</strong></p>${button('ascendant-roll','Roll ascendant · d100')}<div class="field"><label for="mansion-count">Celestial mansions</label>${select('id="mansion-count" data-bind="mansionCount"',Array.from({length:6},(_,i)=>[String(i),i?String(i):'None']),String(chart.mansions.length))}</div>${chart.mansions.map((id,i)=>`<div class="skill-row"><span>${['Sense','Trials','Thought','Love','Coin'][i]}: <strong>${esc(R.astrology.find(x=>x.id===id)?.name||'Not rolled')}</strong></span>${button('mansion-roll','Roll · d100',`data-key="${i}"`)}</div>`).join('')}</details>`:''}`}</section>`;
}
